1	// JSON Pointer (RFC 6901) and JSON Patch (RFC 6902).
2	
3	export class PatchError extends Error {
4	  constructor(message, index) {
5	    super(message);
6	    this.name = 'PatchError';
7	    this.index = index;
8	  }
9	}
10	
11	const OPS = new Set(['add', 'remove', 'replace', 'move', 'copy', 'test']);
12	const INDEX_RE = /^(?:0|[1-9][0-9]*)$/;
13	
14	export function parsePointer(pointer) {
15	  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
16	  if (pointer === '') return [];
17	  if (pointer[0] !== '/' || /~(?![01])/.test(pointer)) throw new SyntaxError('invalid pointer');
18	  return pointer
19	    .slice(1)
20	    .split('/')
21	    .map((t) => t.replace(/~1/g, '/').replace(/~0/g, '~'));
22	}
23	
24	function isObject(v) {
25	  return v !== null && typeof v === 'object' && !Array.isArray(v);
26	}
27	
28	// Defines an own data property, so names like "__proto__" stay ordinary members.
29	function setMember(obj, name, value) {
30	  Object.defineProperty(obj, name, { value, writable: true, enumerable: true, configurable: true });
31	}
32	
33	function deepCopy(v) {
34	  if (Array.isArray(v)) return v.map(deepCopy);
35	  if (isObject(v)) {
36	    const out = {};
37	    for (const k of Object.keys(v)) setMember(out, k, deepCopy(v[k]));
38	    return out;
39	  }
40	  return v;
41	}
42	
43	function deepEqual(a, b) {
44	  if (Array.isArray(a)) {
45	    if (!Array.isArray(b) || a.length !== b.length) return false;
46	    return a.every((x, i) => deepEqual(x, b[i]));
47	  }
48	  if (isObject(a)) {
49	    if (!isObject(b)) return false;
50	    const ka = Object.keys(a);
51	    if (ka.length !== Object.keys(b).length) return false;
52	    return ka.every((k) => Object.hasOwn(b, k) && deepEqual(a[k], b[k]));
53	  }
54	  return a === b;
55	}
56	
57	// Returns the error reason for an operation that breaks the form rules, or null.
58	function checkForm(op) {
59	  if (op === null || typeof op !== 'object' || Array.isArray(op)) return 'not an object';
60	  const name = Object.hasOwn(op, 'op') ? op.op : undefined;
61	  if (typeof name !== 'string' || !OPS.has(name)) return 'bad op';
62	  const path = validPointer(op, 'path');
63	  if (!path) return 'bad path';
64	  let from = null;
65	  if (name === 'move' || name === 'copy') {
66	    from = validPointer(op, 'from');
67	    if (!from) return 'bad from';
68	  }
69	  if ((name === 'add' || name === 'replace' || name === 'test') && !Object.hasOwn(op, 'value')) {
70	    return 'missing value';
71	  }
72	  if (name === 'remove' && path.length === 0) return 'cannot remove root';
73	  if (name === 'move' && from.length < path.length && from.every((t, i) => t === path[i])) {
74	    return 'cannot move into own child';
75	  }
76	  return null;
77	}
78	
79	function validPointer(op, member) {
80	  if (!Object.hasOwn(op, member) || typeof op[member] !== 'string') return null;
81	  try {
82	    return parsePointer(op[member]);
83	  } catch {
84	    return null;
85	  }
86	}
