88	class Failure extends Error {}
89	
90	// Follows tokens from root; returns the value they name or throws a Failure.
91	function resolve(root, tokens, notFound) {
92	  let cur = root;
93	  for (const t of tokens) {
94	    if (Array.isArray(cur)) {
95	      if (t === '-') throw new Failure(notFound);
96	      if (!INDEX_RE.test(t)) throw new Failure('bad index');
97	      if (Number(t) >= cur.length) throw new Failure(notFound);
98	      cur = cur[Number(t)];
99	    } else if (isObject(cur) && Object.hasOwn(cur, t)) {
100	      cur = cur[t];
101	    } else {
102	      throw new Failure(notFound);
103	    }
104	  }
105	  return cur;
106	}
107	
108	function addAt(doc, path, value) {
109	  if (path.length === 0) return value;
110	  const parent = resolve(doc, path.slice(0, -1), 'path not found');
111	  const last = path[path.length - 1];
112	  if (Array.isArray(parent)) {
113	    if (last === '-') {
114	      parent.push(value);
115	    } else if (!INDEX_RE.test(last)) {
116	      throw new Failure('bad index');
117	    } else if (Number(last) > parent.length) {
118	      throw new Failure('path not found');
119	    } else {
120	      parent.splice(Number(last), 0, value);
121	    }
122	  } else if (isObject(parent)) {
123	    setMember(parent, last, value);
124	  } else {
125	    throw new Failure('path not found');
126	  }
127	  return doc;
128	}
129	
130	// Removes the value at a non-empty path that is known to exist.
131	function removeAt(doc, path) {
132	  const parent = resolve(doc, path.slice(0, -1), 'path not found');
133	  const last = path[path.length - 1];
134	  if (Array.isArray(parent)) parent.splice(Number(last), 1);
135	  else delete parent[last];
136	}
137	
138	function applyOne(doc, op) {
139	  const path = parsePointer(op.path);
140	  switch (op.op) {
141	    case 'add':
142	      return addAt(doc, path, deepCopy(op.value));
143	    case 'remove':
144	      resolve(doc, path, 'path not found');
145	      removeAt(doc, path);
146	      return doc;
147	    case 'replace':
148	      if (path.length === 0) return deepCopy(op.value);
149	      resolve(doc, path, 'path not found');
150	      return addAtExisting(doc, path, deepCopy(op.value));
151	    case 'move': {
152	      const from = parsePointer(op.from);
153	      const value = resolve(doc, from, 'from not found');
154	      if (op.from === op.path) return doc;
155	      // The form rules guarantee from is non-empty here (a "" from is a prefix of any other path).
156	      removeAt(doc, from);
157	      return addAt(doc, path, value);
158	    }
159	    case 'copy': {
160	      const value = deepCopy(resolve(doc, parsePointer(op.from), 'from not found'));
161	      return addAt(doc, path, value);
162	    }
163	    case 'test':
164	      if (!deepEqual(resolve(doc, path, 'path not found'), op.value)) throw new Failure('test failed');
165	      return doc;
166	  }
167	}
168	
169	// Replaces the value at a non-empty path that is known to exist, keeping its place.
170	function addAtExisting(doc, path, value) {
171	  const parent = resolve(doc, path.slice(0, -1), 'path not found');
172	  const last = path[path.length - 1];
173	  if (Array.isArray(parent)) parent[Number(last)] = value;
174	  else setMember(parent, last, value);
175	  return doc;
176	}
177	
178	export function applyPatch(doc, patch) {
179	  if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
180	  const ops = [];
181	  for (let i = 0; i < patch.length; i++) {
182	    const op = patch[i];
183	    const reason = checkForm(op);
184	    if (reason) throw new PatchError(`operation ${i}: ${reason}`, i);
185	    ops.push(op);
186	  }
187	  let result = deepCopy(doc);
188	  for (let i = 0; i < ops.length; i++) {
189	    try {
190	      result = applyOne(result, ops[i]);
191	    } catch (err) {
192	      if (err instanceof Failure) throw new PatchError(`operation ${i}: ${err.message}`, i);
193	      throw err;
194	    }
195	  }
196	  return result;
197	}
