2	// Usage: node jsonpatch-cli.mjs <patch> [<doc>]
3	import fs from 'node:fs';
4	import { applyPatch, PatchError } from './jsonpatch.mjs';
5	
6	const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
7	const MAX_BYTES = 1048576;
8	const MAX_DEPTH = 1000;
9	const CHUNK = 65536;
10	
11	class CliError extends Error {
12	  constructor(message, code) {
13	    super(message);
14	    this.code = code;
15	  }
16	}
17	
18	function sleep(ms) {
19	  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
20	}
21	
22	// Reads at most MAX_BYTES + 1 bytes from fd; returns a Buffer or throws an fs error.
23	function readFd(fd) {
24	  const chunks = [];
25	  let total = 0;
26	  for (;;) {
27	    const buf = Buffer.alloc(CHUNK);
28	    let n;
29	    try {
30	      n = fs.readSync(fd, buf, 0, CHUNK, null);
31	    } catch (err) {
32	      if (err.code === 'EAGAIN') {
33	        sleep(10);
34	        continue;
35	      }
36	      throw err;
37	    }
38	    if (n === 0) break;
39	    chunks.push(buf.subarray(0, n));
40	    total += n;
41	    if (total > MAX_BYTES) break;
42	  }
43	  return Buffer.concat(chunks, total);
44	}
45	
46	function readFailure(name, err) {
47	  const reason = err?.code === 'EISDIR' ? 'is a directory' : 'cannot read';
48	  return new CliError(`Error: ${name}: ${reason}`, 1);
49	}
50	
51	function isDirectory(path) {
52	  try {
53	    return fs.statSync(path).isDirectory();
54	  } catch {
55	    return false;
56	  }
57	}
58	
59	function readInput(arg) {
60	  if (arg === '-') {
61	    try {
62	      return readFd(0);
63	    } catch {
64	      throw new CliError('Error: stdin: cannot read', 1);
65	    }
66	  }
67	  let fd;
68	  try {
69	    fd = fs.openSync(arg, 'r');
70	  } catch (err) {
71	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') {
72	      throw new CliError(`Error: ${arg}: no such file`, 1);
73	    }
74	    if (err.code === 'EISDIR' || isDirectory(arg)) throw new CliError(`Error: ${arg}: is a directory`, 1);
75	    throw readFailure(arg, err);
76	  }
77	  try {
78	    if (fs.fstatSync(fd).isDirectory()) throw new CliError(`Error: ${arg}: is a directory`, 1);
79	    return readFd(fd);
80	  } catch (err) {
81	    if (err instanceof CliError) throw err;
82	    throw readFailure(arg, err);
83	  } finally {
84	    fs.closeSync(fd);
85	  }
86	}
87	
88	// Depth of a parsed JSON value, computed without recursion.
89	function depthOf(value) {
90	  let max = 0;
91	  const stack = [[value, 0]];
92	  while (stack.length) {
93	    const [v, d] = stack.pop();
94	    if (v === null || typeof v !== 'object') continue;
95	    const depth = d + 1;
96	    if (depth > max) max = depth;
97	    for (const child of Array.isArray(v) ? v : Object.values(v)) stack.push([child, depth]);
98	  }
99	  return max;
100	}
101	
102	function loadJson(arg) {
103	  const name = arg === '-' ? 'stdin' : arg;
104	  const bytes = readInput(arg);
105	  if (bytes.length > MAX_BYTES) throw new CliError(`Error: ${name}: too large`, 1);
106	  let text;
107	  try {
108	    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
109	  } catch {
110	    throw new CliError(`Error: ${name}: invalid UTF-8`, 3);
111	  }
112	  let value;
113	  try {
114	    value = JSON.parse(text);
115	  } catch {
116	    throw new CliError(`Error: ${name}: invalid JSON`, 3);
117	  }
118	  if (depthOf(value) > MAX_DEPTH) throw new CliError(`Error: ${name}: too deep`, 3);
119	  return value;
120	}
121	
122	function run(args) {
123	  if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
124	  const [patchArg, docArg = '-'] = args;
125	  if (patchArg === '-' && docArg === '-') throw new CliError(USAGE, 2);
126	  const patch = loadJson(patchArg);
127	  const doc = loadJson(docArg);
128	  try {
129	    return applyPatch(doc, patch);
130	  } catch (err) {
131	    if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
132	    throw err;
133	  }
134	}
135	
136	try {
137	  const result = run(process.argv.slice(2));
138	  process.stdout.write(JSON.stringify(result, null, 2) + '\n');
139	  process.exitCode = 0;
140	} catch (err) {
141	  if (!(err instanceof CliError)) throw err;
142	  process.stderr.write(err.message + '\n');
143	  process.exitCode = err.code;
144	}
