54	// Valid JSON '[]' padded with spaces so the result is exactly `total` bytes
55	// (BOM included when withBom is true).
56	export function padded(total, withBom = false) {
57	  const head = withBom ? Buffer.concat([BOM, Buffer.from('[]')]) : Buffer.from('[]');
58	  return Buffer.concat([head, Buffer.alloc(total - head.length, 0x20)]);
59	}
